arguments.command:
cd /workspace/dev && LD_LIBRARY_PATH=/workspace/native SYNECDOCHE_SITE=/workspace/site PYTHONPATH=/workspace/site python3 - <<'EOF' 2>&1 | tail -40
import sys, json, random, io, traceback
sys.path.insert(0,'/workspace/dev'); sys.path.insert(0,'/workspace/submission')
import gen, formats, ref
for i in range(200):
    rnd=random.Random(5000+i)
    req=gen.make_request(rnd)
    data=json.dumps(req).encode()
    try:
        parsed=formats.read_request(io.BytesIO(data))
    except Exception as e:
        print('seed',5000+i,'FORMAT REJECT'); traceback.print_exc(); break
    try:
        import pipeline
        out=pipeline.execute(parsed)
    except Exception as e:
        print('seed',5000+i,'PIPELINE', type(e).__name__, e); traceback.print_exc(); break
    try:
        ref.solve(json.loads(data.decode()))
    except ref.Invalid:
        print('seed',5000+i,'REF INVALID'); break
    except Exception as e:
        print('seed',5000+i,'REF ERR'); traceback.print_exc(); break
EOF
